import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-12-24 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-12-24 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-12-24T00:00:00.000Z","updated":"2019-12-24T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[存储优化]","[性能提升]","[软件开发]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-12-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-12-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,l,s,p,_,u){return i(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>Ceph存储树实现</strong></p><ul><li>讨论了Ceph存储树的实现，特别是容量实现部分，现有实现位于<code>/included/c/CPPp3</code>，需要进一步分离和优化。</li><li>计划将mutator接口与现有的Ceph机械结合，以支持内部节点的突变和分裂操作。</li></ul></li><li><p><strong>现代化的Ceph实现</strong></p><ul><li>探讨了使用Supra Prabhas 17技术对现有Ceph实现进行现代化的可能性，以及现有实现的局限性。</li></ul></li><li><p><strong>Crimson子树的扩展支持</strong></p><ul><li>讨论了为Crimson子树引入新的支持，这是一个较大的扩展，涉及统一不同命令的处理。</li></ul></li><li><p><strong>命令接口的统一与优化</strong></p><ul><li>讨论了统一和优化命令接口的必要性，特别是在处理大型数据集时，提出了逐步实施的计划。</li></ul></li><li><p><strong>OSD终止问题</strong></p><ul><li>讨论了在尝试终止OSD时遇到的问题，特别是在使用SIGINT时，提出了一种可能的解决方案。</li></ul></li><li><p><strong>快照支持与数据复制</strong></p><ul><li>讨论了在OSD级别支持快照的必要性，以及如何通过快照实现更高效的数据复制。</li></ul></li><li><p><strong>SSD优化与硬件控制</strong></p><ul><li>讨论了针对不同类型SSD的优化策略，以及如何通过低级原语更好地利用硬件。</li></ul></li><li><p><strong>ACN问题与单元测试</strong></p><ul><li>讨论了ACN相关的问题，特别是在停止Caster时可能出现的错误，提出了进行更多实验以重现和解决这些问题的计划。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续优化Ceph存储树的实现，特别是容量部分。</li><li>探索使用Supra Prabhas 17技术对Ceph进行现代化的可能性。</li><li>逐步实施命令接口的统一和优化，以提高系统的整体性能。</li><li>测试并实施OSD终止问题的解决方案。</li><li>研究并实施更高效的快照支持机制。</li><li>进行更多实验以优化SSD的使用，并探索硬件级别的并行化。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行Ceph存储树的开发和优化工作。</li><li>探索和实施Ceph的现代化方案。</li><li>逐步统一和优化命令接口，确保与现有系统的兼容性。</li><li>测试并部署OSD终止问题的解决方案。</li><li>研究并实施更高效的快照支持机制。</li><li>进行更多实验以优化SSD的使用，并探索硬件级别的并行化。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议参与者将在接下来的几周内继续跟进各自的工作，并在下一次会议中报告进展。</li></ul><p><strong>会议结束</strong></p><p><strong>下次会议时间：待定</strong></p><p><strong>会议纪要编写人：[您的姓名]</strong></p><p><strong>会议纪要审核人：[审核人姓名]</strong></p><p><strong>会议纪要发布日期：[填写日期]</strong></p>',14)])])}const d=e(r,[["render",o]]);export{S as __pageData,d as default};
